class Solution {
  public int rob(TreeNode root) {
    int[] r = best(root);
    return Math.max(r[0], r[1]);
  }

  // {best without robbing node, best robbing node}
  private int[] best(TreeNode node) {
    if (node == null) return new int[2];
    int[] l = best(node.left), r = best(node.right);
    return new int[] {Math.max(l[0], l[1]) + Math.max(r[0], r[1]), node.val + l[0] + r[0]};
  }
}
